static const uint32_t WIT[60] = {
0xd1c00e,0x9258fd,0xf6b276,0x9544d,0xb51db7,0xef6987,0xc8093a,0x9fd533,0xd0f74f,0x679072,0x1d08d4,0x9d2d59,0x9f9ab9,0x46cf39,0x883bd2,0xc8d85,0xbafa63,0x64ac0c,0xbdb521,0xfdc94d,0x2bd3a6,0xcd5e20,0x7b6576,0xa1af,0xd79793,0x4cbd53,0x81d348,0x6f575a,0x6b03d7,0x467188,0xa80719,0xb5dea,0x11b20b,0xa95504,0x1c04f1,0x6da24,0x409d85,0x11b846,0x51f198,0x9d7771,0xcd2570,0x1bb605,0xdf5d85,0x657a9f,0xf280d0,0xe4108d,0xa1a826,0x572032,0x97bf34,0x62937b,0xc29285,0x745d6f,0xdd4131,0x10c655,0x435eea,0xa89129,0x24a872,0xdc4083,0x9a6389,0x5f6a8c
};

static const uint32_t M22=(1u<<22)-1;
static inline uint32_t rot22(uint32_t x,int k){if(k==0)return x;return ((x<<k)|(x>>(22-k)))&M22;}
static bool covers_radius7_cyclic(uint32_t a,uint32_t* bad=nullptr){
  uint32_t reps[22]; for(int k=0;k<22;k++) reps[k]=rot22(a,k);
  for(uint32_t x=0;x<(1u<<21);++x){
    bool ok=false;
    for(int k=0;k<22;k++){
      int w=__builtin_popcount(x^reps[k]);
      if(w<=7 || w>=15){ok=true;break;}
    }
    if(!ok){if(bad)*bad=x;return false;}
  }
  return true;
}
int main(){
  cout << "R02 I0095 exact finite checker 2026-09-17\n";
  int hist6=0;
  for(int t=0;t<60;t++){
    stringstream ss(HAD24[t]); string z; uint32_t rowbits[24];
    int H[24][24];
    for(int i=0;i<24;i++){
      if(!(ss>>z)){cerr<<"parse fail class "<<t<<"\n";return 2;}
      rowbits[i]=stoul(z,nullptr,16);
      for(int j=0;j<24;j++) H[i][j]=((rowbits[i]>>(23-j))&1u)?1:-1;
    }
    if(ss>>z){cerr<<"extra token class "<<t<<"\n";return 3;}
    for(int i=0;i<24;i++)for(int k=0;k<24;k++){
      int s=0;for(int j=0;j<24;j++)s+=H[i][j]*H[k][j];
      int want=(i==k?24:0); if(s!=want){cerr<<"Hadamard fail class "<<t<<" i="<<i<<" k="<<k<<" got="<<s<<"\n";return 4;}
    }
    uint32_t mask=WIT[t]; int mx=0, norm2=0;
    for(int i=0;i<24;i++){
      int s=0; for(int j=0;j<24;j++){int x=((mask>>j)&1u)?1:-1;s+=H[i][j]*x;}
      mx=max(mx,abs(s)); norm2+=s*s;
    }
    if(mx!=6 || norm2!=576){cerr<<"witness fail class "<<t<<" mx="<<mx<<" norm2="<<norm2<<"\n";return 5;}
    hist6++;
  }
  // Analytical lower bound used in the report: for Hadamard H_24 and any sign x,
  // ||Hx||_2^2=24||x||_2^2=576. If ||Hx||_inf<=4 then <=24*16=384, impossible.
  // All coordinates are even, so discrepancy >=6. The stored witnesses give <=6.
  if(!(576>24*16)){cerr<<"energy inequality fail\n";return 6;}
  cout << "H24_classes_verified="<<hist6<<" each_has_max6_witness=1 energy_lower_bound_forces_ge6=1\n";

  long long necklaces=0; uint32_t bad=0; long long covers=0;
  for(uint32_t a=0;a<(1u<<22);++a){
    int w=__builtin_popcount(a);
    if(w>7) continue; // complement normalization; weights 8..14 fail already at x=0.
    uint32_t mn=a; for(int k=1;k<22;k++) mn=min(mn,rot22(a,k));
    if(a!=mn) continue; // rotation normalization
    necklaces++;
    if(covers_radius7_cyclic(a,&bad)){covers++;cerr<<"unexpected cyclic cover seed="<<hex<<a<<dec<<"\n";return 7;}
  }
  if(necklaces!=12766){cerr<<"necklace count mismatch "<<necklaces<<"\n";return 8;}
  cout << "n22_cyclic_weight_le7_necklaces="<<necklaces<<" radius7_covers="<<covers<<"\n";

  // Exact coverage residual for the best randomized-greedy n=22 quotient code found this run.
  const int C22[22]={1398112,892963,323539,1948110,1053255,1124633,472730,948297,130733,1223786,1603762,1893916,1466799,1742209,525288,432948,245972,775551,2035445,749318,1559179,265358};
  long long uncovered22=0;
  for(uint32_t x=0;x<(1u<<21);++x){
    bool ok=false;
    for(int i=0;i<22;i++){
      int w=__builtin_popcount(x^(uint32_t)C22[i]);
      if(w<=7 || w>=15){ok=true;break;}
    }
    if(!ok) uncovered22++;
  }
  if(uncovered22!=1617){cerr<<"n22 residual mismatch "<<uncovered22<<"\\n";return 9;}
  cout << "n22_best_randomized_greedy_uncovered="<<uncovered22<<" (diagnostic, not a cover)\n";

  cout << "CONCLUSION_H24_ALL_REPRESENTATIVES_DISC6_AND_NO_N22_CIRCULANT_DISC_GE8\n";
  cout << "ALL_EXACT_CHECKS_PASS\n";
  return 0;
}
